        left = self.parse_unary()
        while self.peek() and self.peek()[0] in ('*', '/'):
            op = self.consume()[0]
            right = self.parse_unary()
            if op == '*':
                left = left * right
            else:
                left = int_div(left, right)
        return left

    def parse_unary(self):
        minus_count = 0
        while self.peek() and self.peek()[0] == '-':
            self.consume()
            minus_count += 1

        value = self.parse_primary()

        if minus_count % 2 == 1:
            value = -value

        return value

    def parse_primary(self):
        token = self.peek()
        if token and token[0] == 'NUM':
            self.consume()
            return token[1]
        elif token and token[0] == '(':
            self.consume()
            result = self.parse_expr()
            if self.peek() and self.peek()[0] == ')':
                self.consume()
            return result
        else:
            return 0


